const context = $json;
const allowedTargets = new Set(String(context.allowed_targets_csv || '').split(',').map((value) => value.trim()).filter(Boolean));
if (!allowedTargets.has(context.target)) {
  return [{ json: { ...context, blocked_reason: 'target_not_allowlisted', delivery_status: 'cancelled' } }];
}
return [{ json: { ...context, target_allowed: true, delivery_status: context.dry_run ? 'cancelled' : 'confirmed' } }];

const item = $json;
const whatsappGroupUrl = String(item.whatsapp_group_url || '').trim();
if (!/^https:\/\/(chat\.whatsapp\.com|whatsapp\.com\/channel|wa\.me)\//i.test(whatsappGroupUrl)) { throw new Error('whatsapp_group_url obrigatorio para copy Instagram'); }
const formatMoney = (value) => { if (value === null || value === undefined || value === '') return null; const numberValue = Number(value); if (Number.isFinite(numberValue)) return `R$ ${numberValue.toFixed(2).replace('.', ',')}`; return String(value).trim(); };
const formatRating = (value) => { const rating = Number(value); if (Number.isFinite(rating)) return rating.toFixed(1).replace('.', ','); return String(value || '').trim(); };
const hashtag = String(item.primary_subniche || 'ofertas').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '') || 'ofertas';
const metrics = [formatMoney(item.price) ? `💸 ${formatMoney(item.price)}` : null, formatRating(item.rating) ? `⭐ ${formatRating(item.rating)}/5 na Shopee` : null].filter(Boolean).join('\n');
const captionBase = [[`🔥 ${item.product_name}`, `Copie o link da oferta: ${String(item.offer_link || '').trim()}`].filter(Boolean).join('\n'), metrics, `💬 Quer receber mais ofertas assim?\nEntre no grupo do WhatsApp: ${whatsappGroupUrl}`, '⚠️ Preco e disponibilidade podem mudar.', `#ad #shopee #${hashtag} #achadinhos`].filter(Boolean).join('\n\n');
return [{ json: { ...item, whatsapp_group_url: whatsappGroupUrl, caption_base: captionBase } }];

const item = $json;
const urls = [item.video_url].filter((url) => /^https:\/\//i.test(String(url || '')));
const media_validation = urls.map((url) => ({ url, expected: 'video/', status: 'validated_for_workflow' }));
if (item.instagram_format !== 'reels' || urls.length !== 1) {
  return [{ json: { ...item, media_validation, blocked_reason: 'reels_requires_video_url', delivery_status: 'failed' } }];
}
return [{ json: { ...item, image_urls: [], media_validation, media_revalidation_required: true } }];

const original = $json;
const imageUrls = Array.isArray(original.image_urls) ? original.image_urls.filter(Boolean).slice(0, 10) : [];
if (imageUrls.length < 4) { throw new Error('carousel requires between 4 and 10 image urls'); }
return imageUrls.map((imageUrl, index) => ({ json: { ...original, carousel_image_url: imageUrl, carousel_item_index: index + 1, carousel_item_total: imageUrls.length } }));

const original = $('Montar Copy Instagram').first().json;
const childResponses = $input.all();
const childIds = childResponses.map((item) => String(item.json.id || item.json.creation_id || '').trim()).filter(Boolean);
if (childIds.length < 4 || childIds.length > 10) { throw new Error('carousel requires between 4 and 10 child containers'); }
return [{ json: { ...original, instagram_business_account_id: original.instagram_business_account_id, caption_base: original.caption_base, carousel_child_ids: childIds.join(','), carousel_child_creation_ids: childIds } }];

const item = $json;
const creationId = String(item.creation_id || item.id || '').trim();
if (!creationId) { throw new Error('instagram container creation id ausente'); }
return [{ json: { ...item, creation_id: creationId } }];

const statusResponse = $json;
const normalized = $('Normalizar Container Criado').first().json;
let original = null;
try { original = $('Aguardar Container Instagram').first().json; } catch (error) { original = null; }
if (!original || !String(original.instagram_business_account_id || '').trim()) { try { original = $('Montar Payload Pai Carrossel').first().json; } catch (error) { original = null; } }
if (!original || !String(original.instagram_business_account_id || '').trim()) { original = $('Montar Copy Instagram').first().json; }
return [{ json: { ...original, creation_id: String(normalized.creation_id || '').trim(), container_status: String(statusResponse.status_code || '').trim(), instagram_graph_container_id: String(statusResponse.id || '').trim(), poll_attempt: Number(original.poll_attempt || 0) + 1 } }];

const publishResponse = $json;
const original = $('Restaurar Contexto Publicacao').first().json;
const instagramMediaId = String(publishResponse.id || '').trim();
if (!instagramMediaId) { throw new Error('instagram media publish id ausente'); }
return [{ json: { ...original, instagram_media_id: instagramMediaId, delivery_status: 'confirmed' } }];

const item = $json;
const template_id = Math.floor(Math.random() * 10) + 1;
return [{ json: { ...item, template_id, template_folder_id: '1Fk_D3IXQ_qMZikJ5UBwIV2xTDa0Rwj2W' } }];

const context = $('Selecionar Template Reels').first().json;
const expected = `template_${String(context.template_id).padStart(2, '0')}.ass`;
const matches = $input.all().filter((entry) => String(entry.json.name || '') === expected);
if (matches.length !== 1) throw new Error(`template ASS ausente ou ambiguo: ${expected}`);
return [{ json: { ...context, ass_file_id: matches[0].json.id, ass_file_name: expected } }];

const context = $('Escolher Template ASS Reels').first().json;
const binary = $input.first().binary?.ass_template?.data;
if (!binary) throw new Error('ASS template nao retornado pelo Google Drive');
const safe = (value) => String(value || '').replace(/[^A-Za-z0-9_-]/g, '-').slice(0, 40);
const job_id = `reels-${safe(context.dispatch_plan_id)}-${safe(context.item_id)}-t${context.template_id}`;
return [{ json: {
  ...context,
  job_id,
  ass_template_base64: binary,
  ass_asset_version: context.ass_file_id,
  render_status: 'queued',
  render_attempts: 0,
} }];

const response = $json || {};
const original = $('Montar Payload Render Reels').first().json;
const failed = Boolean(response.error || Number(response.statusCode || 0) >= 400 || !String(response.job_id || '').trim());
return [{ json: { ...original, ...response, job_id: response.job_id || original.job_id, render_status: failed ? 'failed_fallback_original' : (response.render_status || response.status || 'queued'), render_error_code: failed ? 'RENDER_SUBMIT_FAILED' : '', render_error_log: failed ? String(response.error || response.message || '').slice(0, 2000) : '', poll_attempt: 0 } }];

const response = $json;
const original = $('Normalizar Job Render Reels').first().json;
const errors = Array.isArray(response.errors) ? response.errors : [];
return [{ json: {
  ...original,
  ...response,
  job_id: response.job_id || original.job_id,
  render_status: response.render_status || response.status || 'running',
  render_attempts: Number(response.attempts || original.render_attempts || 0),
  poll_attempt: Number(original.poll_attempt || 0) + 1,
  render_error_code: errors.at(-1)?.code || '',
  render_error_log: errors.map((error) => error.message || '').join(' | ').slice(0, 2000),
  published_video_url: response.artifact_url || '',
} }];

return [{ json: {
  ...$json,
  render_status: 'failed_fallback_original',
  overlay_applied: false,
  published_video_source: 'shopee_original',
  published_video_url: '',
} }];
